mapper.select:
select
suggest.*,
proprietor.name
from suggest suggest
left join proprietor proprietor on suggest.user_id = proprietor.id

    and suggest.id = #{id}
    and suggest.user_id = #{userId}
    and suggest.content = #{content}
    and suggest.answer = #{answer}
    and suggest.status = #{status}
    and suggest.create_time = #{createTime}
    and suggest.title like concat('%',#{title},'%')
    and proprietor.name like concat('%',#{name},'%')


    limit #{current},#{pageSize}

select count(*) from suggest suggest
left join proprietor proprietor on suggest.user_id = proprietor.id

    and suggest.id = #{id}
    and suggest.user_id = #{userId}
    and suggest.content = #{content}
    and suggest.answer = #{answer}
    and suggest.status = #{status}
    and suggest.create_time = #{createTime}
    and suggest.title like concat('%',#{title},'%')
    and proprietor.name like concat('%',#{name},'%')
